        long rowId = db.insert(SUDOKU_TABLE_NAME, "name", values);
        if (rowId > 0) {
            return rowId;
        }
        throw new SQLException("Failed to insert sudoku.");
    }

    public long importSudoku(long folderID, SudokuImportParams pars) throws SudokuInvalidFormatException {
        if (pars.data == null) {
            throw new SudokuInvalidFormatException(pars.data);
        }
        if (!CellCollection.isValid(pars.data, CellCollection.DATA_VERSION_PLAIN) && !CellCollection.isValid(pars.data, CellCollection.DATA_VERSION_1)) {
            throw new SudokuInvalidFormatException(pars.data);
        }
        if (this.mInsertSudokuStatement == null) {
            SQLiteDatabase db = this.mOpenHelper.getWritableDatabase();
            this.mInsertSudokuStatement = db.compileStatement("insert into sudoku (folder_id, created, state, time, last_played, data, puzzle_note) values (?, ?, ?, ?, ?, ?, ?)");
        }
        this.mInsertSudokuStatement.bindLong(1, folderID);
        this.mInsertSudokuStatement.bindLong(2, pars.created);
        this.mInsertSudokuStatement.bindLong(3, pars.state);
        this.mInsertSudokuStatement.bindLong(4, pars.time);
        this.mInsertSudokuStatement.bindLong(5, pars.lastPlayed);
        this.mInsertSudokuStatement.bindString(6, pars.data);
        if (pars.note == null) {
            this.mInsertSudokuStatement.bindNull(7);
        } else {
            this.mInsertSudokuStatement.bindString(7, pars.note);
        }
        long rowId = this.mInsertSudokuStatement.executeInsert();
        if (rowId > 0) {
            return rowId;
        }
        throw new SQLException("Failed to insert sudoku.");
    }

