    private Cell(int value, CellNote note, boolean editable, boolean valid) {
        this.mCellCollectionLock = new Object();
        this.mRowIndex = -1;
        this.mColumnIndex = -1;
        if (value < 0 || value > 9) {
            throw new IllegalArgumentException("Value must be between 0-9.");
        }
