        synchronized (this.mCellCollectionLock) {
            this.mCellCollection = cellCollection;
        }
        this.mRowIndex = rowIndex;
        this.mColumnIndex = colIndex;
        this.mSector = sector;
        this.mRow = row;
        this.mColumn = column;
