    }

    public static Cell deserialize(StringTokenizer data) {
        Cell cell = new Cell();
        cell.setValue(Integer.parseInt(data.nextToken()));
        cell.setNote(CellNote.deserialize(data.nextToken()));
        cell.setEditable(Boolean.valueOf(data.nextToken().equals("1")));
        return cell;
    }

    public static Cell deserialize(String cellData) {
        StringTokenizer data = new StringTokenizer(cellData, "|");
        return deserialize(data);
    }

    public void serialize(StringBuilder data) {
        data.append(this.mValue).append("|");
        if (this.mNote == null || this.mNote.isEmpty()) {
            data.append("-").append("|");
        } else {
            this.mNote.serialize(data);
            data.append("|");
        }
        data.append(this.mEditable ? "1" : "0").append("|");
    }

    public String serialize() {
        StringBuilder sb = new StringBuilder();
        serialize(sb);
        return sb.toString();
    }

    private void onChange() {
        synchronized (this.mCellCollectionLock) {
            if (this.mCellCollection != null) {
                this.mCellCollection.onChange();
            }
        }
    }
}

