    }

    public void markAllCellsAsValid() {
        this.mOnChangeEnabled = false;
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                this.mCells[r][c].setValid(true);
            }
        }
        this.mOnChangeEnabled = true;
        onChange();
    }

    public boolean validate() {
        boolean valid = true;
        markAllCellsAsValid();
        this.mOnChangeEnabled = false;
        for (CellGroup row : this.mRows) {
            if (!row.validate()) {
                valid = false;
            }
        }
        for (CellGroup column : this.mColumns) {
            if (!column.validate()) {
                valid = false;
            }
        }
        for (CellGroup sector : this.mSectors) {
            if (!sector.validate()) {
                valid = false;
            }
        }
        this.mOnChangeEnabled = true;
        onChange();
        return valid;
    }

    public boolean isCompleted() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = this.mCells[r][c];
                if (cell.getValue() == 0 || !cell.isValid()) {
                    return false;
                }
            }
        }
        return true;
    }

    public void markAllCellsAsEditable() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = this.mCells[r][c];
                cell.setEditable(true);
            }
        }
    }

    public void markFilledCellsAsNotEditable() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = this.mCells[r][c];
                cell.setEditable(Boolean.valueOf(cell.getValue() == 0));
            }
        }
    }

    public Map<Integer, Integer> getValuesUseCount() {
        Map<Integer, Integer> valuesUseCount = new HashMap<>();
        for (int value = 1; value <= 9; value++) {
            valuesUseCount.put(Integer.valueOf(value), 0);
        }
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                int value2 = getCell(r, c).getValue();
                if (value2 != 0) {
                    valuesUseCount.put(Integer.valueOf(value2), Integer.valueOf(valuesUseCount.get(Integer.valueOf(value2)).intValue() + 1));
                }
            }
        }
        return valuesUseCount;
    }

    private void initCollection() {
        this.mRows = new CellGroup[9];
        this.mColumns = new CellGroup[9];
        this.mSectors = new CellGroup[9];
        for (int i = 0; i < 9; i++) {
            this.mRows[i] = new CellGroup();
            this.mColumns[i] = new CellGroup();
            this.mSectors[i] = new CellGroup();
        }
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = this.mCells[r][c];
                cell.initCollection(this, r, c, this.mSectors[((c / 3) * 3) + (r / 3)], this.mRows[c], this.mColumns[r]);
            }
        }
    }

    public static CellCollection deserialize(StringTokenizer data) {
        Cell[][] cells = (Cell[][]) Array.newInstance((Class<?>) Cell.class, 9, 9);
        int r = 0;
        int c = 0;
        while (data.hasMoreTokens() && r < 9) {
            cells[r][c] = Cell.deserialize(data);
            c++;
            if (c == 9) {
                r++;
                c = 0;
            }
        }
        return new CellCollection(cells);
    }

    public static CellCollection deserialize(String data) {
        String[] lines = data.split("\n");
        if (lines.length == 0) {
            throw new IllegalArgumentException("Cannot deserialize Sudoku, data corrupted.");
        }
        if (!lines[0].equals("version: 1")) {
            return fromString(data);
        }
        StringTokenizer st = new StringTokenizer(lines[1], "|");
        return deserialize(st);
    }

    public static CellCollection fromString(String data) {
        Cell[][] cells = (Cell[][]) Array.newInstance((Class<?>) Cell.class, 9, 9);
        int pos = 0;
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                int value = 0;
                while (true) {
                    if (pos >= data.length()) {
                        break;
                    }
                    pos++;
                    if (data.charAt(pos - 1) >= '0' && data.charAt(pos - 1) <= '9') {
                        value = data.charAt(pos - 1) - '0';
                        break;
                    }
                }
                Cell cell = new Cell();
                cell.setValue(value);
                cell.setEditable(Boolean.valueOf(value == 0));
                cells[r][c] = cell;
            }
        }
        return new CellCollection(cells);
    }

    public String serialize() {
        StringBuilder sb = new StringBuilder();
        serialize(sb);
        return sb.toString();
    }

    public void serialize(StringBuilder data) {
        data.append("version: 1\n");
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = this.mCells[r][c];
                cell.serialize(data);
            }
        }
    }

    public static boolean isValid(String data, int dataVersion) {
        if (dataVersion == DATA_VERSION_PLAIN) {
            return DATA_PATTERN_VERSION_PLAIN.matcher(data).matches();
        }
        if (dataVersion == DATA_VERSION_1) {
            return DATA_PATTERN_VERSION_1.matcher(data).matches();
        }
        throw new IllegalArgumentException("Unknown version: " + dataVersion);
    }

    public void addOnChangeListener(OnChangeListener listener) {
        if (listener == null) {
            throw new IllegalArgumentException("The listener is null.");
        }
        synchronized (this.mChangeListeners) {
            if (this.mChangeListeners.contains(listener)) {
                throw new IllegalStateException("Listener " + listener + "is already registered.");
            }
            this.mChangeListeners.add(listener);
        }
    }

    public void removeOnChangeListener(OnChangeListener listener) {
        if (listener == null) {
            throw new IllegalArgumentException("The listener is null.");
        }
        synchronized (this.mChangeListeners) {
            if (!this.mChangeListeners.contains(listener)) {
                throw new IllegalStateException("Listener " + listener + " was not registered.");
            }
            this.mChangeListeners.remove(listener);
        }
    }

    protected void onChange() {
        if (this.mOnChangeEnabled) {
            synchronized (this.mChangeListeners) {
                for (OnChangeListener l : this.mChangeListeners) {
                    l.onChange();
                }
            }
        }
    }
}

