public class ClearAllNotesCommand extends AbstractCellCommand {
    private List<NoteEntry> mOldNotes = new ArrayList();

    @Override // cz.shudu.opensudoku.game.command.AbstractCommand
    void saveState(Bundle outState) {
        int[] rows = new int[this.mOldNotes.size()];
        int[] cols = new int[this.mOldNotes.size()];
        String[] notes = new String[this.mOldNotes.size()];
        int i = 0;
        for (NoteEntry ne : this.mOldNotes) {
            rows[i] = ne.rowIndex;
            cols[i] = ne.colIndex;
            notes[i] = ne.note.serialize();
            i++;
        }
        outState.putIntArray("rows", rows);
        outState.putIntArray("cols", cols);
        outState.putStringArray("notes", notes);
    }

    @Override // cz.shudu.opensudoku.game.command.AbstractCommand
    void restoreState(Bundle inState) {
        int[] rows = inState.getIntArray("rows");
        int[] cols = inState.getIntArray("cols");
        String[] notes = inState.getStringArray("notes");
        for (int i = 0; i < rows.length; i++) {
            this.mOldNotes.add(new NoteEntry(rows[i], cols[i], CellNote.deserialize(notes[i])));
        }
    }

    @Override // cz.shudu.opensudoku.game.command.AbstractCommand
    void execute() {
        CellCollection cells = getCells();
        this.mOldNotes.clear();
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = cells.getCell(r, c);
                CellNote note = cell.getNote();
                if (!note.isEmpty()) {
                    this.mOldNotes.add(new NoteEntry(r, c, note));
                    cell.setNote(new CellNote());
                }
            }
        }
    }

    @Override // cz.shudu.opensudoku.game.command.AbstractCommand
    void undo() {
        CellCollection cells = getCells();
        for (NoteEntry ne : this.mOldNotes) {
            cells.getCell(ne.rowIndex, ne.colIndex).setNote(ne.note);
        }
    }

