package cz.shudu.opensudoku.game;

public class FolderInfo {
    public long id;
    public String name;
    public int playingCount;
    public int puzzleCount;
    public int solvedCount;

    public FolderInfo() {
    }

    public FolderInfo(long id, String name) {
        this.id = id;
        this.name = name;
    }

    public String getDetail(Context c) {
        StringBuilder sb = new StringBuilder();
        if (this.puzzleCount == 0) {
            sb.append(c.getString(R.string.no_puzzles));
        } else {
            sb.append(this.puzzleCount == 1 ? c.getString(R.string.one_puzzle) : c.getString(R.string.n_puzzles, Integer.valueOf(this.puzzleCount)));
            int unsolvedCount = this.puzzleCount - this.solvedCount;
            if (this.playingCount != 0 || unsolvedCount != 0) {
                sb.append(" (");
                if (this.playingCount != 0) {
                    sb.append(c.getString(R.string.n_playing, Integer.valueOf(this.playingCount)));
                    if (unsolvedCount != 0) {
                        sb.append(", ");
                    }
                }
                if (unsolvedCount != 0) {
                    sb.append(c.getString(R.string.n_unsolved, Integer.valueOf(unsolvedCount)));
                }
                sb.append(")");
            }
            if (unsolvedCount == 0 && this.puzzleCount != 0) {
                sb.append(" (").append(c.getString(R.string.all_solved)).append(")");
            }
        }
        return sb.toString();
    }
}

