        this.mActiveFromTime = SystemClock.uptimeMillis();
    }

    public void pause() {
        this.mTime += SystemClock.uptimeMillis() - this.mActiveFromTime;
        this.mActiveFromTime = -1L;
        setLastPlayed(System.currentTimeMillis());
    }

    private void finish() {
        pause();
        this.mState = 2;
    }

    public void reset() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                Cell cell = this.mCells.getCell(r, c);
