package cz.shudu.opensudoku.gui.inputmethod;

    public void activateInputMethod(int methodID) {
        if (methodID < -1 || methodID >= this.mInputMethods.size()) {
            throw new IllegalArgumentException(String.format("Invalid method id: %s.", Integer.valueOf(methodID)));
        }
        ensureInputMethods();
        if (this.mActiveMethodIndex != -1) {
            this.mInputMethods.get(this.mActiveMethodIndex).deactivate();
        }
        boolean idFound = false;
        int id = methodID;
        int numOfCycles = 0;
        if (id != -1) {
            while (true) {
                if (0 != 0 || numOfCycles > this.mInputMethods.size()) {
                    break;
                }
                if (this.mInputMethods.get(id).isEnabled()) {
                    ensureControlPanel(id);
                    idFound = true;
                    break;
                } else {
                    id++;
                    if (id == this.mInputMethods.size()) {
                        id = 0;
                    }
                    numOfCycles++;
                }
            }
        }
        if (!idFound) {
            id = -1;
        }
        int i = 0;
        while (i < this.mInputMethods.size()) {
            InputMethod im = this.mInputMethods.get(i);
            if (im.isInputMethodViewCreated()) {
                im.getInputMethodView().setVisibility(i == id ? 0 : 8);
            }
            i++;
        }
        this.mActiveMethodIndex = id;
        if (this.mActiveMethodIndex != -1) {
            InputMethod activeMethod = this.mInputMethods.get(this.mActiveMethodIndex);
            activeMethod.activate();
            if (this.mHintsQueue != null) {
                this.mHintsQueue.showOneTimeHint(activeMethod.getInputMethodName(), activeMethod.getNameResID(), activeMethod.getHelpResID(), new Object[0]);
            }
        }
    }

