        StateBundle cpState = new StateBundle(this.mPreferences, String.valueOf(PREFIX) + ".", true);
        cpState.putInt("activeMethodIndex", controlPanel.getActiveMethodIndex());
        cpState.commit();
        for (InputMethod im : controlPanel.getInputMethods()) {
            StateBundle outState = new StateBundle(this.mPreferences, String.valueOf(PREFIX) + "." + im.getInputMethodName(), true);
            im.onSaveState(outState);
            outState.commit();
        }
