    @Override // android.view.View
    public boolean onTouchEvent(MotionEvent event) {
        if (!this.mReadonly) {
            int x = (int) event.getX();
            int y = (int) event.getY();
            switch (event.getAction()) {
                case 0:
                case 2:
                    this.mTouchedCell = getCellAtPoint(x, y);
                    break;
                case 1:
                    this.mSelectedCell = getCellAtPoint(x, y);
                    invalidate();
                    if (this.mSelectedCell != null) {
                        onCellTapped(this.mSelectedCell);
                        onCellSelected(this.mSelectedCell);
                    }
                    if (this.mAutoHideTouchedCellHint) {
                        this.mTouchedCell = null;
                        break;
                    }
                    break;
                case 3:
                    this.mTouchedCell = null;
                    break;
            }
            postInvalidate();
        }
        return !this.mReadonly;
    }

    @Override // android.view.View, android.view.KeyEvent.Callback
    public boolean onKeyDown(int keyCode, KeyEvent event) {
        if (!this.mReadonly) {
            switch (keyCode) {
                case 7:
                case 62:
                case 67:
                    if (this.mSelectedCell == null) {
                        return true;
                    }
                    if (event.isShiftPressed() || event.isAltPressed()) {
                        setCellNote(this.mSelectedCell, CellNote.EMPTY);
                        return true;
                    }
                    setCellValue(this.mSelectedCell, 0);
                    moveCellSelectionRight();
                    return true;
                case 19:
                    return moveCellSelection(0, -1);
                case 20:
                    return moveCellSelection(0, 1);
                case 21:
                    return moveCellSelection(-1, 0);
                case 22:
                    return moveCellSelection(1, 0);
                case 23:
                    if (this.mSelectedCell == null) {
                        return true;
                    }
                    onCellTapped(this.mSelectedCell);
                    return true;
                default:
                    if (keyCode >= 8 && keyCode <= 16) {
                        int selNumber = keyCode - 7;
                        Cell cell = this.mSelectedCell;
                        if (event.isShiftPressed() || event.isAltPressed()) {
                            setCellNote(cell, cell.getNote().toggleNumber(selNumber));
                            return true;
                        }
                        setCellValue(cell, selNumber);
                        moveCellSelectionRight();
                        return true;
                    }
                    break;
            }
        }
        return false;
    }

    public void moveCellSelectionRight() {
        if (!moveCellSelection(1, 0)) {
            int selRow = this.mSelectedCell.getRowIndex();
            if (!moveCellSelectionTo(selRow + 1, 0)) {
                moveCellSelectionTo(0, 0);
            }
        }
        postInvalidate();
    }

    private void setCellValue(Cell cell, int value) {
        if (cell.isEditable()) {
            if (this.mGame != null) {
                this.mGame.setCellValue(cell, value);
            } else {
                cell.setValue(value);
            }
        }
    }

    private void setCellNote(Cell cell, CellNote note) {
        if (cell.isEditable()) {
            if (this.mGame != null) {
                this.mGame.setCellNote(cell, note);
            } else {
                cell.setNote(note);
            }
        }
    }

    private boolean moveCellSelection(int vx, int vy) {
        int newRow = 0;
        int newCol = 0;
        if (this.mSelectedCell != null) {
            newRow = this.mSelectedCell.getRowIndex() + vy;
            newCol = this.mSelectedCell.getColumnIndex() + vx;
        }
        return moveCellSelectionTo(newRow, newCol);
    }

    private boolean moveCellSelectionTo(int row, int col) {
        if (col < 0 || col >= 9 || row < 0 || row >= 9) {
            return false;
        }
        this.mSelectedCell = this.mCells.getCell(row, col);
        onCellSelected(this.mSelectedCell);
        postInvalidate();
        return true;
    }

    private Cell getCellAtPoint(int x, int y) {
        int lx = x - getPaddingLeft();
        int ly = y - getPaddingTop();
        int row = (int) (ly / this.mCellHeight);
        int col = (int) (lx / this.mCellWidth);
        if (col < 0 || col >= 9 || row < 0 || row >= 9) {
            return null;
        }
        return this.mCells.getCell(row, col);
    }
