    private void savePuzzle() {
        this.mGame.getCells().markFilledCellsAsNotEditable();
        switch (this.mState) {
            case 0:
                this.mDatabase.updateSudoku(this.mGame);
                Toast.makeText(getApplicationContext(), R.string.puzzle_updated, 0).show();
                break;
            case 1:
