                this.mGame.setCreated(System.currentTimeMillis());
                this.mDatabase.insertSudoku(this.mFolderID, this.mGame);
                Toast.makeText(getApplicationContext(), R.string.puzzle_inserted, 0).show();
                break;
        }
    }
