        private String getDateAndTimeForHumans(long datetime) {
            Date date = new Date(datetime);
            Date now = new Date(System.currentTimeMillis());
            Date today = new Date(now.getYear(), now.getMonth(), now.getDate());
            Date yesterday = new Date(System.currentTimeMillis() - 86400000);
            return date.after(today) ? this.mContext.getString(R.string.at_time, this.mTimeFormatter.format(date)) : date.after(yesterday) ? this.mContext.getString(R.string.yesterday_at_time, this.mTimeFormatter.format(date)) : this.mContext.getString(R.string.on_date, this.mDateTimeFormatter.format(date));
        }

