                    board.setReadOnly(true);
                    board.setFocusable(false);
                    ((SudokuBoardView) view).setCells(cells);
                    break;
                case R.id.state /* 2131230756 */:
                    TextView label = (TextView) view;
                    String stateString = null;
                    switch (state) {
                        case 0:
                            stateString = this.mContext.getString(R.string.playing);
                            break;
                        case 2:
                            stateString = this.mContext.getString(R.string.solved);
                            break;
                    }
                    label.setVisibility(stateString == null ? 8 : 0);
                    label.setText(stateString);
                    if (state == 2) {
                        label.setTextColor(Color.rgb(187, 187, 187));
                        break;
                    } else {
                        label.setTextColor(Color.rgb(255, 255, 255));
                        break;
                    }
                case R.id.time /* 2131230757 */:
                    long time = c.getLong(columnIndex);
                    TextView label2 = (TextView) view;
                    String timeString = null;
                    if (time != 0) {
                        timeString = this.mGameTimeFormatter.format(time);
                    }
                    label2.setVisibility(timeString == null ? 8 : 0);
                    label2.setText(timeString);
                    if (state == 2) {
                        label2.setTextColor(Color.rgb(187, 187, 187));
                        break;
                    } else {
                        label2.setTextColor(Color.rgb(255, 255, 255));
                        break;
                    }
                case R.id.last_played /* 2131230758 */:
                    long lastPlayed = c.getLong(columnIndex);
                    TextView label3 = (TextView) view;
                    String lastPlayedString = null;
                    if (lastPlayed != 0) {
                        lastPlayedString = this.mContext.getString(R.string.last_played_at, getDateAndTimeForHumans(lastPlayed));
                    }
                    label3.setVisibility(lastPlayedString == null ? 8 : 0);
                    label3.setText(lastPlayedString);
                    break;
                case R.id.created /* 2131230759 */:
                    long created = c.getLong(columnIndex);
                    TextView label4 = (TextView) view;
                    String createdString = null;
                    if (created != 0) {
                        createdString = this.mContext.getString(R.string.created_at, getDateAndTimeForHumans(created));
                    }
                    label4.setVisibility(createdString == null ? 4 : 0);
                    label4.setText(createdString);
                    break;
                case R.id.note /* 2131230760 */:
                    String note = c.getString(columnIndex);
                    TextView label5 = (TextView) view;
                    if (note == null || note.trim() == "") {
                        ((TextView) view).setVisibility(8);
                    } else {
                        ((TextView) view).setText(note);
                    }
                    label5.setVisibility((note == null || note.trim().equals("")) ? 8 : 0);
                    label5.setText(note);
                    break;
            }
            return true;
        }

