                Timer.this.mLastLogTime = now;
                Timer timer = Timer.this;
                Timer timer2 = Timer.this;
                int i = timer2.mTickCount;
                timer2.mTickCount = i + 1;
                if (!timer.step(i, Timer.this.mAccumTime)) {
                    Timer.this.mNextTime += Timer.this.mTickInterval;
                    if (Timer.this.mNextTime <= now) {
                        Timer.this.mNextTime += Timer.this.mTickInterval;
                    }
                    Timer.this.postAtTime(Timer.this.runner, Timer.this.mNextTime);
                    return;
                }
                Timer.this.mIsRunning = false;
                Timer.this.done();
            }
        }
    };
    private long mAccumTime = 0;

